actions.script:
import java.util.regex.Pattern
import java.util.regex.Matcher

// Generate unique novel ID
novelId = ec.entity.sequencedIdPrimary

// Validate input
if (!textContent || textContent.trim().isEmpty()) {
    ec.message.addError("Text content cannot be empty")
    return
}

// Clean and normalize text content
String cleanContent = textContent.replaceAll(/\r\n/, '\n')
                                .replaceAll(/\r/, '\n')
                                .replaceAll(/\n{3,}/, '\n\n')
                                .trim()

// Detect chapters using pattern matching
List<Map> chapters = []
String[] lines = cleanContent.split('\n')

// Chapter detection patterns
List<Pattern> chapterPatterns = [
    Pattern.compile(/^第[一二三四五六七八九十\d]+章/),
    Pattern.compile(/^Chapter\s+(\d+|[IVXLCDM]+)/, Pattern.CASE_INSENSITIVE),
    Pattern.compile(/^第\s*(\d+)\s*章/),
    Pattern.compile(/^章节\s*(\d+)/),
    Pattern.compile(/^\d+\.\s/),
    Pattern.compile(/^[IVXLCDM]+\.\s/, Pattern.CASE_INSENSITIVE),
    Pattern.compile(/^-{3,}\s*第.*章\s*-{3,}/),
    Pattern.compile(/^={3,}\s*Chapter.*={3,}/, Pattern.CASE_INSENSITIVE),
    Pattern.compile(/^第[0-9]+章/)
]

Map currentChapter = null
List<String> chapterContent = []
int chapterNumber = 0

for (int i = 0; i < lines.length; i++) {
    String line = lines[i].trim()

    // Check if line matches chapter pattern
    boolean isChapterStart = chapterPatterns.any { pattern ->
        pattern.matcher(line).find()
    }

    if (isChapterStart) {
        // Save previous chapter
        if (currentChapter && chapterContent.size() > 0) {
            String content = chapterContent.join('\n').trim()
            currentChapter.content = content
            currentChapter.wordCount = countWords(content)
            chapters.add(currentChapter)
        }

        // Start new chapter
        chapterNumber++
        String chapterId = "chapter_${chapterNumber}"
        currentChapter = [
            id: chapterId,
            title: line ?: "Chapter ${chapterNumber}",
            content: '',
            wordCount: 0,
            chapterNumber: chapterNumber
        ]
        chapterContent = []
    } else if (line.length() > 0) {
        chapterContent.add(line)
    } else if (chapterContent.size() > 0) {
        chapterContent.add('')
    }
}

// Don't forget the last chapter
if (currentChapter && chapterContent.size() > 0) {
    String content = chapterContent.join('\n').trim()
    currentChapter.content = content
    currentChapter.wordCount = countWords(content)
    chapters.add(currentChapter)
}

// If no chapters detected, treat as single chapter
if (chapters.size() == 0 && cleanContent.length() > 0) {
    chapters.add([
        id: 'chapter_1',
        title: 'Chapter 1',
        content: cleanContent,
        wordCount: countWords(cleanContent),
        chapterNumber: 1
    ])
}

// Calculate total word count
int totalWordCount = chapters.sum { it.wordCount } ?: 0

// Create novel structure
novelStructure = [
    title: title ?: extractTitleFromContent(cleanContent),
    author: author ?: 'Unknown Author',
    chapters: chapters,
    metadata: [
        wordCount: totalWordCount,
        language: detectLanguage(cleanContent),
        description: generateDescription(cleanContent)
    ]
]

// Store in database
ec.entity.makeValue("Novel").setAll([
    novelId: novelId,
    title: novelStructure.title,
    author: novelStructure.author,
    originalText: textContent,
    wordCount: totalWordCount,
    status: 'parsed',
    createdDate: ec.user.nowTimestamp,
    lastUpdated: ec.user.nowTimestamp
]).create()

// Store chapters
chapters.each { chapter ->
    ec.entity.makeValue("Chapter").setAll([
        chapterId: ec.entity.sequencedIdPrimary,
        novelId: novelId,
        chapterNumber: chapter.chapterNumber,
        title: chapter.title,
        content: chapter.content,
        wordCount: chapter.wordCount,
        createdDate: ec.user.nowTimestamp
    ]).create()
}

ec.logger.info("Novel parsed successfully: ${novelStructure.title} with ${chapters.size()} chapters")

// Helper functions
int countWords(String text) {
    if (!text) return 0

    // Count Chinese characters
    int chineseChars = (text =~ /[\u4e00-\u9fa5]/).size()

    // Count English words
    String englishText = text.replaceAll(/[\u4e00-\u9fa5]/, '')
    int englishWords = (englishText =~ /\b\w+\b/).size()

    return chineseChars + englishWords
}

String detectLanguage(String text) {
    int chineseChars = (text =~ /[\u4e00-\u9fa5]/).size()
    int totalChars = text.length()

    return (chineseChars / totalChars > 0.3) ? 'zh' : 'en'
}

String generateDescription(String text) {
    String[] sentences = text.split(/[。！？.!?]/)
    List<String> validSentences = sentences.findAll { it.trim().length() > 0 }
    String description = validSentences.take(3).join('。')
    return description.length() > 200 ? description.substring(0, 200) + '...' : description
}

String extractTitleFromContent(String content) {
    String[] lines = content.split('\n')
    for (String line : lines) {
        line = line.trim()
        if (line.length() > 0 && line.length() < 100) {
            return line
        }
    }
    return 'Untitled Novel'
}

List<String> errors = []
List<String> warnings = []

// Check file extension
if (fileName) {
    String extension = fileName.toLowerCase().substring(fileName.lastIndexOf('.'))
    if (extension != '.txt') {
        errors.add("Unsupported file format: ${extension}. Only TXT files are supported.")
    }
}

// Check content
if (!fileContent || fileContent.trim().isEmpty()) {
    errors.add("File content is empty. Please upload a file with content.")
} else {
    // Check file size (approximate)
    int contentSize = fileContent.getBytes('UTF-8').length
    int maxSize = 1024 * 1024 // 1MB

    if (contentSize > maxSize) {
        errors.add("File size exceeds maximum allowed size (1MB).")
    }

    if (contentSize < 1000) {
        warnings.add("File appears to be very small. Please ensure it contains a complete novel.")
    }

    // Check for common encoding issues
    if (fileContent.contains('\uFFFD')) {
        warnings.add("File may have encoding issues. Some characters might not display correctly.")
    }
}

isValid = errors.size() == 0
errorMessage = errors.join('; ')
warnings = warnings

if (!isValid) {
    ec.logger.warn("File validation failed: ${errorMessage}")
}

// Implementation will be added in subsequent tasks
plotStructure = [:]
keyEvents = []
